"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";

/** เน€เธงเธฅเธฒเนเธซเน progress เธงเธดเนเธเธเธฒเธ 0 โ’ 100% (เธ•เนเธญเธเธเธฃเธ 100% เธเนเธญเธเธ–เธถเธเธเธฐเน€เธเนเธฒเน€เธงเนเธ) */
const PROGRESS_DURATION_MS = 2500;
/** เธซเธฅเธฑเธเธ–เธถเธ 100% เนเธฅเนเธง เธฃเธญเน€เธซเนเธเธ•เธฑเธงเน€เธฅเธเธชเธฑเธเธเธฃเธนเนเธเนเธญเธ fade out */
const HOLD_AT_100_MS = 400;

export default function PageLoader() {
    const [progress, setProgress] = useState(0);
    const [isReady, setIsReady] = useState(false);
    const [isExited, setIsExited] = useState(false);
    const [pageLoaded, setPageLoaded] = useState(false);
    const [progressDone, setProgressDone] = useState(false);

    // Progress เธงเธดเนเธ 0 โ’ 100% เธ•เธฒเธกเน€เธงเธฅเธฒ
    useEffect(() => {
        const start = Date.now();
        const progressInterval = setInterval(() => {
            const elapsed = Date.now() - start;
            const p = Math.min(100, (elapsed / PROGRESS_DURATION_MS) * 100);
            setProgress(p);
            if (p >= 100) {
                setProgressDone(true);
                clearInterval(progressInterval);
            }
        }, 32);
        return () => clearInterval(progressInterval);
    }, []);

    // เธฃเธญเธ—เธฑเนเธ progress 100% เนเธฅเธฐ window load เนเธฅเนเธงเธเนเธญเธขเน€เธเนเธฒเน€เธงเนเธ
    useEffect(() => {
        if (!progressDone || !pageLoaded) return;
        const t = setTimeout(() => setIsReady(true), HOLD_AT_100_MS);
        return () => clearTimeout(t);
    }, [progressDone, pageLoaded]);

    useEffect(() => {
        const onLoad = () => setPageLoaded(true);
