"use client";

import React, { createContext, useContext, useMemo, ReactNode, useState, useEffect } from "react";
import { MotionConfig, conservativeMotionConfig } from "./motion.config";
import { useReducedMotion } from "./useReducedMotion";
import { useDeviceProfile, DeviceProfile } from "./useDeviceProfile";
import { resolveMotionConfig } from "./motion.guard";

interface MotionContextValue {
    reducedMotion: boolean;
    deviceProfile: DeviceProfile;
    motionConfig: MotionConfig;
    interactionMode: "desktop" | "mobile";
    isReady: boolean;
    isPhone: boolean; // true only for phones (not tablet) โ€” use for lightweight CTA / 3D count
}

const MotionContext = createContext<MotionContextValue | undefined>(undefined);

export function MotionProvider({ children }: { children: ReactNode }) {
    // 1. Hook into browser capabilities (Client-side detection)
    const reducedMotion = useReducedMotion();
    const deviceProfile = useDeviceProfile();

    // 2. State for Config
    // Start with strictly conservative config to match SSR
    const [finalConfig, setFinalConfig] = useState<MotionConfig>(conservativeMotionConfig);
    const [isReady, setIsReady] = useState(false);

    // 3. Effect to Resolve Config (Upgrade Phase)
    useEffect(() => {
        // Resolve the best possible config logic based on detections
        const computedConfig = resolveMotionConfig(conservativeMotionConfig, reducedMotion, deviceProfile);

        // Update state to trigger re-render with enhanced features
        setFinalConfig(computedConfig);
        setIsReady(true);
    }, [reducedMotion, deviceProfile]); // Re-run if these change (e.g. user plugs in mouse)

    // 4. Determine Interaction Mode
    const interactionMode = (deviceProfile.isMobile ? "mobile" : "desktop") as "desktop" | "mobile";

    // 5. Memoize Context Value
    const isPhone = deviceProfile.isPhone;
    const value = useMemo<MotionContextValue>(() => ({
        reducedMotion,
        deviceProfile,
        motionConfig: finalConfig,
        interactionMode,
        isReady,
        isPhone
    }), [reducedMotion, deviceProfile, finalConfig, interactionMode, isReady, isPhone]);

    return (
        <MotionContext.Provider value={value}>
            {children}
        </MotionContext.Provider>
    );
}

// Internal export mostly for testing, usually public API is useMotion
export function useMotionContext() {
    const context = useContext(MotionContext);
    if (!context) {
        throw new Error("useMotionContext must be used within a MotionProvider");
    }
    return context;
}

"use client";

import { useState, useEffect } from "react";

// Extend Navigator interface strictly for experimental API properties
interface ExtendedNavigator extends Navigator {
    deviceMemory?: number;
    hardwareConcurrency: number; // Must be required to match Navigator
}

export type PerformanceTier = "low" | "medium" | "high";

export interface DeviceProfile {
    isMobile: boolean;
    isTablet: boolean;
    isPhone: boolean;
    isLowEnd: boolean;
    hasFinePointer: boolean;
    performanceTier: PerformanceTier;
    cpuCores: number | undefined;
    memoryGB: number | undefined;
}

// Conservative SSR defaults to avoid hydration mismatch
const defaultProfile: DeviceProfile = {
    isMobile: false,
    isTablet: false,
    isPhone: false,
    isLowEnd: false,
    hasFinePointer: true,
    performanceTier: "high",
    cpuCores: undefined,
    memoryGB: undefined,
};

/**
 * Hook to detect detailed device capabilities.
 * Determines performance tier based on CPU cores and RAM.
 */
export function useDeviceProfile(): DeviceProfile {
    // 1. Initialize with specific default state
    const [profile, setProfile] = useState<DeviceProfile>(defaultProfile);

    useEffect(() => {
        // Safe check for browser environment
        if (typeof window === "undefined" || typeof navigator === "undefined") {
            return;
        }

        const nav = navigator as ExtendedNavigator;

        // --- 1. Interaction Detection ---
        const hasFinePointer = window.matchMedia("(pointer: fine)").matches;
        const hasCoarsePointer = window.matchMedia("(pointer: coarse)").matches;
        const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(nav.userAgent);

        const isMobile = isMobileUA || hasCoarsePointer;

        // Tablet: iPad or large touch screen (treat like desktop for Hero 3D + full CTA)
        const isIpad = /iPad|Macintosh.*Mac OS X.*Safari/i.test(nav.userAgent) || (nav.platform === "MacIntel" && typeof navigator.maxTouchPoints === "number" && navigator.maxTouchPoints > 1);
        const isLargeTouch = isMobile && typeof window !== "undefined" && window.innerWidth >= 768;
        const isTablet = isIpad || isLargeTouch;
        const isPhone = isMobile && !isTablet;

        // --- 2. Hardware Detection ---
        // deviceMemory is in GB (RAM)
        // hardwareConcurrency is logical cores
        const cpuCores = nav.hardwareConcurrency;
        const memoryGB = nav.deviceMemory;

        // --- 3. Performance Tiering ---
        let tier: PerformanceTier = "high";
        let lowEnd = false;

        // Logic:
        // High: > 4 cores AND > 4GB RAM (Modern Desktop/High-end Mobile)
        // Mid:  <= 4 cores OR <= 4GB RAM 
        // Low:  < 4 cores OR < 2GB RAM (Old phones/Laptops)

        if (cpuCores && memoryGB) {
            if (cpuCores <= 4 || memoryGB <= 4) {
                tier = "medium";
            }
            if (cpuCores < 4 || memoryGB < 4) {
                tier = "low";
                lowEnd = true;
            }
        } else {
            // Fallback if APIs are missing (Safari/Firefox often hide this info):
            // If mobile -> assume medium
            // If desktop -> assume high
            if (isMobile) {
                tier = "medium";
            }
        }

        // --- 4. State Update ---
        setProfile({
            isMobile,
            isTablet,
            isPhone,
            isLowEnd: lowEnd,
            hasFinePointer,
            performanceTier: tier,
            cpuCores,
            memoryGB
        });

    }, []); // Run once on mount

    return profile;
}

"use client";

import { useState, useEffect } from "react";

/**
 * Hook to detect if the user has requested the system to minimize the amount
 * of non-essential motion it uses.
 * 
 * Safe for SSR (Defaults to false).
 */
export function useReducedMotion(): boolean {
    const [matches, setMatches] = useState<boolean>(false);

    useEffect(() => {
        // SSR Safe Check
        if (typeof window === "undefined" || !window.matchMedia) {
            return;
        }

        const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");

        // Set initial value
        setMatches(mediaQuery.matches);

        // Define listener
        const listener = (event: MediaQueryListEvent) => {
            setMatches(event.matches);
        };

        // Modern event listener
        if (mediaQuery.addEventListener) {
            mediaQuery.addEventListener("change", listener);
            return () => mediaQuery.removeEventListener("change", listener);
        } else {
            // Fallback for older browsers (though unlikely needed for modern apps)
            mediaQuery.addListener(listener);
            return () => mediaQuery.removeListener(listener);
        }
    }, []);

    return matches;
}
